const articles = [
  {
    source: 'plans-and-pricing',
    text: 'Acme Cloud Drive has three plans. Free includes 15 GB of storage. Plus costs $4 per month and includes 200 GB. Pro costs $10 per month and includes 2 TB. Paying yearly gives two months free. You can upgrade at any time and the price difference is prorated for the current billing period.',
  },
  {
    source: 'file-limits',
    text: 'The largest single file you can upload is 5 GB on the Free plan and 50 GB on Plus and Pro. Uploads from the web app pause if the browser tab is closed and resume automatically when you open Acme Cloud Drive again. The desktop app uploads in the background.',
  },
  {
    source: 'restore-deleted-files',
    text: 'Deleted files move to Trash. Free accounts can restore files from Trash for 30 days. Plus and Pro accounts can restore them for 180 days. After that, files are permanently erased and support cannot recover them. To restore, open Trash, select the files and click Restore.',
  },
  {
    source: 'sharing-links',
    text: 'Anyone with a share link can view a file without an account. Plus and Pro users can protect a link with a password and set an expiry date. Links on the Free plan never expire until you turn them off. Editing a shared file requires the other person to have an Acme account.',
  },
  {
    source: 'two-factor-authentication',
    text: 'Two-factor authentication is available on every plan. Turn it on under Settings, then Security. Acme supports authenticator apps and hardware security keys. SMS codes are not supported. Save your eight recovery codes when you enable it, because support cannot disable two-factor authentication for you.',
  },
  {
    source: 'delete-account',
    text: 'To delete your account, go to Settings, then Account, then Delete account. Your files are kept for 14 days in case you change your mind, then permanently erased. Cancel any paid plan first, because deleting the account does not issue a refund for the remaining billing period.',
  },
];

return articles.map((a) => ({ json: a }));

const testCase = $('Current test case').first().json;
const docs = $input.all().map((item) => item.json).filter((j) => j.document);

const retrievedSources = docs.map((d) => d.document.metadata?.source ?? 'unknown');
const context = docs
  .map((d, i) => `[${i + 1}] (source: ${retrievedSources[i]})\n${d.document.pageContent}`)
  .join('\n\n');

return [{
  json: {
    ...testCase,
    retrievedSources,
    context: context || '(no documents were retrieved)',
    startedAt: Date.now(),
  },
}];

