const s = $('Set monitor settings').first().json;
const c = $('Build context').first().json;
const answer = String($('Generate answer').first().json.text ?? '').trim();
const judgeText = String($input.first().json.text ?? '');

let verdict = null;
const match = judgeText.match(/\{[\s\S]*\}/);
if (match) {
  try {
    verdict = JSON.parse(match[0]);
  } catch (e) {
    verdict = null;
  }
}

const toScore = (v) => {
  const n = Math.round(Number(v));
  return Number.isFinite(n) ? Math.min(5, Math.max(1, n)) : null;
};
const groundedness = toScore(verdict?.groundedness);
const correctness = toScore(verdict?.correctness);
const abstained = verdict?.abstained === true;

const answerable = Boolean(c.expectedSource);
const rank = answerable ? c.retrievedSources.indexOf(c.expectedSource) + 1 : 0;
const retrievalHit = answerable ? rank > 0 : null;

const failures = [];
if (!verdict || groundedness === null || correctness === null) {
  failures.push('judge output could not be parsed');
} else if (answerable) {
  if (!retrievalHit) failures.push(`expected source "${c.expectedSource}" was not retrieved`);
  if (abstained) failures.push('declined a question the documents answer');
  if (groundedness < s.minGroundedness) failures.push(`groundedness ${groundedness}/5`);
  if (correctness < s.minCorrectness) failures.push(`correctness ${correctness}/5`);
} else if (!abstained) {
  failures.push('answered a question the documents do not cover');
}

return [{
  json: {
    caseId: c.caseId,
    question: c.question,
    answerable,
    expectedSource: c.expectedSource,
    retrievedSources: c.retrievedSources.join(', '),
    rank,
    retrievalHit,
    groundedness,
    correctness,
    abstained,
    passed: failures.length === 0,
    failReason: failures.join('; '),
    answer: answer.slice(0, 500),
    judgeReason: String(verdict?.reason ?? '').slice(0, 300),
    latencyMs: Date.now() - c.startedAt,
  },
}];

const cases = $input.all().map((item) => item.json).filter((j) => j.caseId);
const answerable = cases.filter((c) => c.answerable);
const outOfScope = cases.filter((c) => !c.answerable);

const pct = (n, d) => (d ? Math.round((1000 * n) / d) / 10 : null);
const mean = (values) => {
  const v = values.filter((x) => typeof x === 'number');
  return v.length ? Math.round((100 * v.reduce((a, b) => a + b, 0)) / v.length) / 100 : null;
};

const failed = cases.filter((c) => !c.passed);

return [{
  json: {
    runAt: new Date().toISOString(),
    cases: cases.length,
    passRate: pct(cases.length - failed.length, cases.length),
    retrievalHitRate: pct(answerable.filter((c) => c.retrievalHit).length, answerable.length),
    avgGroundedness: mean(answerable.map((c) => c.groundedness)),
    avgCorrectness: mean(answerable.map((c) => c.correctness)),
    abstentionRate: pct(outOfScope.filter((c) => c.abstained).length, outOfScope.length),
    avgLatencyMs: Math.round(mean(cases.map((c) => c.latencyMs)) ?? 0),
    failedCases: failed.map((c) => `${c.caseId}: ${c.failReason}`).join('\n'),
    executionId: $execution.id,
  },
}];

const s = $('Set monitor settings').first().json;
const cur = $('Summarize run').first().json;
const last = $input.first().json;
const previous = typeof last.passRate === 'number' ? last : null;

const problems = [];
const below = (value, min) => value !== null && value < min;

if (below(cur.retrievalHitRate, s.minRetrievalHitRate)) {
  problems.push(`Retrieval hit rate ${cur.retrievalHitRate}% (minimum ${s.minRetrievalHitRate}%)`);
}
if (below(cur.avgGroundedness, s.minGroundedness)) {
  problems.push(`Average groundedness ${cur.avgGroundedness}/5 (minimum ${s.minGroundedness})`);
}
if (below(cur.avgCorrectness, s.minCorrectness)) {
  problems.push(`Average correctness ${cur.avgCorrectness}/5 (minimum ${s.minCorrectness})`);
}
if (below(cur.abstentionRate, s.minAbstentionRate)) {
  problems.push(`Declined only ${cur.abstentionRate}% of out-of-scope questions (minimum ${s.minAbstentionRate}%)`);
}
if (previous && previous.passRate - cur.passRate >= s.maxPassRateDrop) {
  problems.push(`Pass rate dropped from ${previous.passRate}% to ${cur.passRate}% since the last run`);
}

return [{
  json: {
    ...cur,
    previousPassRate: previous ? previous.passRate : null,
    status: problems.length ? 'degraded' : 'healthy',
    problems: problems.join('\n'),
  },
}];

